using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using Il2CppInterop.Runtime.InteropTypes;

namespace PTTRCustomWeapons.Game
{
    /// <summary>
    /// Name-based access to the game's own classes (generated by MelonLoader from GameAssembly.dll).
    /// Il2CppInterop exposes the game's fields as properties, so "members" means properties, fields
    /// and parameterless methods.
    /// </summary>
    internal static class Reflect
    {
        private static List<Assembly>? _gameAssemblies;
        private static readonly Dictionary<string, Type?> TypeCache = new Dictionary<string, Type?>(StringComparer.OrdinalIgnoreCase);
        private static readonly Dictionary<(Type, string), MemberInfo?> MemberCache = new Dictionary<(Type, string), MemberInfo?>();

        private static readonly string[] EngineAssemblyPrefixes =
        {
            "UnityEngine", "Unity.", "Il2Cppmscorlib", "Il2CppSystem", "Il2CppMono", "Il2CppInterop", "System", "mscorlib",
            "Mono.", "MelonLoader", "0Harmony", "Il2CppNewtonsoft", "Il2CppDOTween", "Il2Cpp__Generated", "netstandard",
            "Microsoft.", "Tomlet", "AssetRipper", "AssetsTools", "bHaptics", "Iced", "MonoMod",
        };

        public static IReadOnlyList<Assembly> GameAssemblies
        {
            get
            {
                if (_gameAssemblies != null) return _gameAssemblies;
                var found = new Dictionary<string, Assembly>(StringComparer.OrdinalIgnoreCase);
                // Make sure the generated game assemblies are loaded (nothing references them before us).
                var dir = Path.Combine(U.GameRoot, "MelonLoader", "Il2CppAssemblies");
                if (Directory.Exists(dir))
                {
                    foreach (var file in Directory.GetFiles(dir, "*.dll"))
                    {
                        var name = Path.GetFileNameWithoutExtension(file);
                        if (!IsGameAssemblyName(name)) continue;
                        try { found[name] = Assembly.Load(new AssemblyName(name)); }
                        catch (Exception ex) { Log.Warn($"Could not load game assembly {name}: {ex.Message}"); }
                    }
                }
                foreach (var a in AppDomain.CurrentDomain.GetAssemblies())
                {
                    var name = a.GetName().Name ?? "";
                    if (IsGameAssemblyName(name) && !found.ContainsKey(name)) found[name] = a;
                }
                _gameAssemblies = found.Values.ToList();
                if (_gameAssemblies.Count == 0) Log.Warn("No game assemblies found - is MelonLoader set up for IL2CPP?");
                return _gameAssemblies;
            }
        }

        private static bool IsGameAssemblyName(string name)
        {
            if (name.Equals("PTTRCustomWeapons", StringComparison.OrdinalIgnoreCase)) return false;
            if (name.StartsWith("Assembly-CSharp", StringComparison.OrdinalIgnoreCase)) return true;
            if (name.StartsWith("Il2Cpp", StringComparison.OrdinalIgnoreCase) && !name.StartsWith("Il2CppInterop") && !name.StartsWith("Il2Cppmscorlib")
                && !name.StartsWith("Il2CppSystem") && !name.StartsWith("Il2CppMono")) return true; // e.g. Il2CppAssembly-CSharp in some setups
            return !EngineAssemblyPrefixes.Any(p => name.StartsWith(p, StringComparison.OrdinalIgnoreCase));
        }

        public static IEnumerable<Type> AllGameTypes()
        {
            foreach (var a in GameAssemblies)
            {
                Type[] types;
                try { types = a.GetTypes(); }
                catch (ReflectionTypeLoadException ex) { types = ex.Types.Where(t => t != null).ToArray()!; }
                catch { continue; }
                foreach (var t in types)
                    if (t != null && !t.Name.StartsWith("<") && typeof(Il2CppObjectBase).IsAssignableFrom(t)) yield return t;
            }
        }

        /// <summary>Finds a game class by simple name (namespace ignored), case-insensitive.</summary>
        public static Type? FindType(string name)
        {
            if (TypeCache.TryGetValue(name, out var cached)) return cached;
            Type? best = null;
            foreach (var t in AllGameTypes())
            {
                if (!t.Name.Equals(name, StringComparison.OrdinalIgnoreCase) && !(t.FullName ?? "").Equals(name, StringComparison.OrdinalIgnoreCase)) continue;
                if (best == null || (!t.IsNested && best.IsNested)) best = t;
            }
            TypeCache[name] = best;
            return best;
        }

        public static Type? FindFirstType(IEnumerable<string> names, Func<Type, bool>? filter = null)
        {
            foreach (var n in names)
            {
                var t = FindType(n);
                if (t != null && (filter == null || filter(t))) return t;
            }
            return null;
        }

        private static bool IsEngineDeclared(MemberInfo m)
        {
            var asm = m.DeclaringType?.Assembly.GetName().Name ?? "";
            return !IsGameAssemblyName(asm);
        }

        private static readonly string[] WildcardExclusions =
        {
            "mult", "chance", "sound", "audio", "prefab", "particle", "fx", "icon", "anim", "color", "colour", "material",
            "layer", "mask", "type", "ptr", "nativefield", "bone", "path", "scene", "index", "timer", "delay", "sprite", "prefix",
        };

        /// <summary>
        /// Finds a member by name: property, field or parameterless method. "*word*" matches any member
        /// containing the word (only members declared by the game, and only of a type accepted by <paramref name="typeOk"/>).
        /// </summary>
        public static MemberInfo? FindMember(Type type, string name, Func<Type, bool>? typeOk = null, string? filterKey = null)
        {
            // results are cached when there is no filter, or the caller names the filter
            bool cacheable = typeOk == null || filterKey != null;
            var key = (type, name + "#" + filterKey);
            if (cacheable && MemberCache.TryGetValue(key, out var cached)) return cached;

            MemberInfo? result = null;
            const BindingFlags flags = BindingFlags.Public | BindingFlags.Instance | BindingFlags.FlattenHierarchy;
            bool wildcard = name.StartsWith("*") || name.EndsWith("*");
            var needle = name.Trim('*').ToLowerInvariant();

            IEnumerable<MemberInfo> candidates = type.GetProperties(flags).Where(p => p.GetIndexParameters().Length == 0 && p.CanRead).Cast<MemberInfo>()
                .Concat(type.GetFields(flags))
                .Concat(type.GetMethods(flags).Where(m => m.GetParameters().Length == 0 && m.ReturnType != typeof(void) && !m.IsSpecialName && !m.IsGenericMethod));

            foreach (var m in candidates)
            {
                var memberType = MemberType(m);
                if (memberType == null) continue;
                if (typeOk != null && !typeOk(memberType)) continue;
                var lower = m.Name.ToLowerInvariant();
                if (wildcard)
                {
                    if (IsEngineDeclared(m)) continue;
                    if (!lower.Contains(needle)) continue;
                    if (WildcardExclusions.Any(x => x != needle && lower.Contains(x) && !needle.Contains(x))) continue;
                }
                else if (!m.Name.Equals(name, StringComparison.OrdinalIgnoreCase)) continue;

                // prefer properties/fields over methods, and exact-case matches
                if (result == null || (result is MethodInfo && !(m is MethodInfo)) || (m.Name == name && result.Name != name)) result = m;
            }
            if (cacheable) MemberCache[key] = result;
            return result;
        }

        public static Type? MemberType(MemberInfo m) => m switch
        {
            PropertyInfo p => p.PropertyType,
            FieldInfo f => f.FieldType,
            MethodInfo mi => mi.ReturnType,
            _ => null
        };

        public static object? GetValue(object target, MemberInfo m)
        {
            try
            {
                return m switch
                {
                    PropertyInfo p => p.GetValue(target),
                    FieldInfo f => f.GetValue(target),
                    MethodInfo mi => mi.Invoke(target, null),
                    _ => null
                };
            }
            catch (TargetInvocationException ex) { throw ex.InnerException ?? ex; }
        }

        public static bool SetValue(object target, MemberInfo m, object? value)
        {
            switch (m)
            {
                case PropertyInfo p when p.CanWrite: p.SetValue(target, value); return true;
                case FieldInfo f when !f.IsInitOnly: f.SetValue(target, value); return true;
                default: return false;
            }
        }

        /// <summary>Reads the first resolvable path from <paramref name="paths"/> ("a.b" walks sub-objects).</summary>
        public static object? GetFirst(object target, IEnumerable<string> paths, Func<Type, bool>? typeOk, string? filterKey, out string? usedPath)
        {
            foreach (var path in paths)
            {
                try
                {
                    var holder = WalkToHolder(target, path, cloneAssets: false, out var last);
                    if (holder == null) continue;
                    var m = FindMember(holder.GetType(), last, typeOk, filterKey);
                    if (m == null) continue;
                    usedPath = path.Contains('*') ? path.Replace(last, m.Name) : path;
                    return GetValue(holder, m);
                }
                catch { /* try next */ }
            }
            usedPath = null;
            return null;
        }

        /// <summary>Writes <paramref name="value"/> into the first writable path that has a compatible type.</summary>
        public static bool SetFirst(object target, IEnumerable<string> paths, object value, out string? usedPath)
        {
            foreach (var path in paths)
            {
                try
                {
                    var holder = WalkToHolder(target, path, cloneAssets: true, out var last);
                    if (holder == null) continue;
                    var m = FindMember(holder.GetType(), last, t => CanConvert(value, t));
                    if (m == null || m is MethodInfo) continue;
                    var memberType = MemberType(m)!;
                    if (!TryConvert(value, memberType, out var converted)) continue;
                    if (!SetValue(holder, m, converted)) continue;
                    usedPath = (path.Contains('.') ? path.Substring(0, path.LastIndexOf('.') + 1) : "") + m.Name;
                    return true;
                }
                catch { /* try next */ }
            }
            usedPath = null;
            return false;
        }

        /// <summary>
        /// Follows "a.b.c" up to the object that holds "c". Shared data assets (ScriptableObjects) on the way are
        /// cloned first when writing, so changing one custom weapon never changes the game's original weapon.
        /// </summary>
        private static object? WalkToHolder(object target, string path, bool cloneAssets, out string last)
        {
            var parts = path.Split('.');
            last = parts[^1];
            object? cur = target;
            for (int i = 0; i < parts.Length - 1 && cur != null; i++)
            {
                var m = FindMember(cur.GetType(), parts[i]);
                if (m == null) return null;
                var next = GetValue(cur, m);
                if (cloneAssets && next is UnityEngine.Object uo && !(next is UnityEngine.Component) && !(next is UnityEngine.GameObject))
                {
                    try
                    {
                        var copy = UnityEngine.Object.Instantiate(uo);
                        var typed = Activator.CreateInstance(next.GetType(), copy.Pointer);
                        if (SetValue(cur, m, typed)) next = typed;
                    }
                    catch (Exception ex) { Log.WarnOnce("clone" + path, $"Could not copy shared data '{parts[i]}': {ex.Message}"); }
                }
                cur = next;
            }
            return cur;
        }

        private static bool IsNumeric(Type t) =>
            t == typeof(float) || t == typeof(double) || t == typeof(int) || t == typeof(long) || t == typeof(short) || t == typeof(byte) || t == typeof(uint);

        public static bool CanConvert(object value, Type target)
        {
            if (target.IsInstanceOfType(value)) return true;
            if (value is string) return target == typeof(string) || target.IsEnum;
            if (value is bool) return target == typeof(bool);
            if (IsNumeric(value.GetType())) return IsNumeric(target) || target.IsEnum;
            return false;
        }

        public static bool TryConvert(object value, Type target, out object? result)
        {
            result = null;
            try
            {
                if (target.IsInstanceOfType(value)) { result = value; return true; }
                if (target.IsEnum)
                {
                    if (value is string s)
                    {
                        var names = Enum.GetNames(target);
                        var match = names.FirstOrDefault(n => n.Equals(s, StringComparison.OrdinalIgnoreCase))
                                    ?? names.FirstOrDefault(n => n.IndexOf(s, StringComparison.OrdinalIgnoreCase) >= 0 || s.IndexOf(n, StringComparison.OrdinalIgnoreCase) >= 0);
                        if (match == null) return false;
                        result = Enum.Parse(target, match);
                        return true;
                    }
                    result = Enum.ToObject(target, Convert.ToInt64(value));
                    return true;
                }
                if (IsNumeric(target) && IsNumeric(value.GetType()))
                {
                    double d = Convert.ToDouble(value);
                    if (target == typeof(int) || target == typeof(long) || target == typeof(short) || target == typeof(byte) || target == typeof(uint))
                        d = Math.Round(d);
                    result = Convert.ChangeType(d, target);
                    return true;
                }
                if (target == typeof(bool) && value is bool) { result = value; return true; }
                if (target == typeof(string)) { result = value.ToString(); return true; }
            }
            catch { }
            return false;
        }

        /// <summary>Wraps an Il2Cpp object pointer as the given game type (e.g. a Component as the game's Enemy class).</summary>
        public static object? Wrap(Type gameType, Il2CppObjectBase obj)
        {
            if (obj == null) return null;
            try { return Activator.CreateInstance(gameType, obj.Pointer); }
            catch { return null; }
        }

        public static string Describe(Type t)
        {
            static string N(Type x) => x.IsGenericType ? x.Name.Split('`')[0] + "<" + string.Join(",", x.GetGenericArguments().Select(N)) + ">" : x.Name;
            return N(t);
        }
    }
}
